#!/usr/bin/env bash
# APEX UserPromptSubmit Hook — Reference Doc Lazy Injection
# Fires before each user message. Injects ONLY the reference doc
# relevant to the current query. Zero tokens if no match.
#
# Research: 15,000 tokens/session recovered by keyword-triggered injection
# vs loading all 23 reference docs (~30,364 tokens) upfront.
#
# Configure: add to .claude/settings.json under UserPromptSubmit
# Generated by APEX hooks_generator.py

PROMPT="${1:-}"
REFS=".claude/references"

[ -z "$PROMPT" ] && exit 0
[ ! -d "$REFS" ] && exit 0

PROMPT_LOWER=$(echo "$PROMPT" | tr '[:upper:]' '[:lower:]')

inject() {
    local file="$REFS/$1"
    [ -f "$file" ] && cat "$file" && exit 0
}

# Framework-specific
echo "$PROMPT_LOWER" | grep -qE 'next\.?js|app router|server component|server action|route handler' && inject "nextjs-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE 'react|component|hook|usestate|useeffect|jsx|tsx' && inject "react-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE 'vue|nuxt|svelte|sveltekit|astro' && inject "vue-svelte-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE '\bdjango\b|django orm|django view|django model' && inject "django-patterns.md"
echo "$PROMPT_LOWER" | grep -qE '\brails\b|activerecord|active record|ruby on rails' && inject "rails-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE 'fastapi|pydantic|async def|fastapi route' && inject "fastapi-patterns.md"
echo "$PROMPT_LOWER" | grep -qE '\bgo\b|golang|goroutine|go module|gin |echo |fiber ' && inject "go-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE 'react native|flutter|swiftui|ios|android|mobile' && inject "native-guidelines.md"

# Domain-specific
echo "$PROMPT_LOWER" | grep -qE 'sql|postgres|mysql|supabase|query|database|orm|prisma|drizzle|migration' && inject "sql-patterns.md"
echo "$PROMPT_LOWER" | grep -qE 'tailwind|shadcn|ui component|css|styling|design system|token|variant' && inject "shadcn-tailwind-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE 'test|spec|jest|pytest|vitest|cypress|playwright|coverage|tdd|unit test' && inject "testing-patterns.md"
echo "$PROMPT_LOWER" | grep -qE 'security|auth|permission|rls|jwt|token|csrf|injection|xss|secret|credential' && inject "security-checklist.md"
echo "$PROMPT_LOWER" | grep -qE 'api|rest|endpoint|route|openapi|swagger|graphql|grpc|webhook' && inject "api-design.md"
echo "$PROMPT_LOWER" | grep -qE 'mcp|model context protocol|tool|server|claude tool' && inject "mcp-guide.md"
echo "$PROMPT_LOWER" | grep -qE 'chart|graph|icon|svg|visualization|d3|recharts|chart\.js' && inject "charts-icons-reference.md"
echo "$PROMPT_LOWER" | grep -qE 'page layout|landing|hero|card|grid|flex|responsive|mobile first' && inject "page-patterns.md"
echo "$PROMPT_LOWER" | grep -qE 'ux|user experience|accessibility|a11y|wcag|aria|usability' && inject "ux-principles.md"
echo "$PROMPT_LOWER" | grep -qE 'inspiration|animation|motion|framer|gsap|aesthetic|dark neon|glassmorphism' && inject "inspiration.md"
echo "$PROMPT_LOWER" | grep -qE 'agent|multi.agent|worktree|spawn|parallel|orchestrat' && inject "agent-protocol.md"
echo "$PROMPT_LOWER" | grep -qE 'python|pip|virtualenv|async python|type hint' && inject "python-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE 'typescript|type error|interface|type alias|generics|zod|ts config' && inject "react-guidelines.md"
echo "$PROMPT_LOWER" | grep -qE 'debug|error|crash|bug|fix|broken|not working|issue|stack trace' && inject "troubleshooting.md"

# No match — inject nothing. Zero tokens.
exit 0
